"""Generate the off-hand copies' STATES into DECORATE.aedual.

Modelled on BD22 1.92's own gen_dual.py, whose output (DECORATE.rsqdual, 308 KB) begins:

    // 1.20 GENERATED by gen_dual.py: the off-hand copies of BD22's guns. Do not edit by hand.
    // Each copy is its gun, renamed, with its own magazine; it lives in the off hand only.

That is the whole trick, and nothing smaller works. A weapon's states name their magazine
LITERALLY -- eight times in this set's pistol alone -- so an off-hand copy that merely
declares `Weapon.AmmoType1 "<its own magazine>"` and inherits its parent's states will load
the PARENT's magazine every time. Measured here on 2026-10-23 before this existed: reload the
off pistol and PistolClip went 108 -> 96, PistolLoaded 0 -> 12, AE_M4A3PistolMagOff 0 -> 0.
The off-hand gun could never hold a round, and reloading it quietly refilled the other gun.

So each copy gets its parent's whole state machine with the magazine class name substituted,
exactly as BD22 does it. The RESERVE is not substituted: both hands draw from the same pouch,
as BD22's copies share Clip1.

    python -I tools/gen_aedual_states.py          # rewrites DECORATE.aedual in place
"""
import io
import os
import re
import sys

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))

# off-hand actor -> (parent gun, the parent's magazine class, the copy's own magazine)
GUNS = [
    ('AE_Off_M4A3Pistol',    'M4A3Pistol_3D',        'PistolLoaded',        'AE_M4A3PistolMagOff'),
    ('AE_Off_MercPistol',    'MercPistol_3D',        'PistolLoaded',        'AE_MercPistolMagOff'),
    ('AE_Off_SynthPistol',   'SynthPistol_3D',       'SynthLoaded',         'AE_SynthPistolMagOff'),
    ('AE_Off_YutaniPistol',  'YutaniPistol_3D',      'YPistolLoaded',       'AE_YutaniPistolMagOff'),
    ('AE_Off_NewShotgun',    'NewShotgun_3D',        'ShotgunLoaded',       'AE_NewShotgunMagOff'),
    ('AE_Off_YutaniShotgun', 'YutaniShotgun_3D',     'YShotgunLoaded',      'AE_YutaniShotgunMagOff'),
    ('AE_Off_PulseRifle',    'PulseRifle_3D',        'PulseLoaded',         'AE_PulseRifleMagOff'),
    ('AE_Off_YutaniRifle',   'YutaniRifle_3D',       'YPulseLoaded',        'AE_YutaniRifleMagOff'),
    ('AE_Off_Flamer',        'M240Flamethrower_3D',  'FlamethrowerLoaded',  'AE_FlamerMagOff'),
    ('AE_Off_YutaniFlamer',  'YutaniFlamer_3D',      'YutanithrowerLoaded', 'AE_YutaniFlamerMagOff'),
]

SRC = ['pistol.txt', 'shotgun.txt', 'rifle.txt', 'flamethrower.txt', 'smartgun.txt', 'grenade.txt']


def strip_states(body):
    """Remove an existing States { } block from an actor body.

    NOT IDEMPOTENT BEFORE THIS: the splice below finds the actor's closing brace and inserts a
    fresh States block in front of it without removing one already there, so a second run gave
    every off-hand actor TWO States blocks. The shipped DECORATE.aedual has exactly one each
    (counted), so nothing was broken -- but the next person to re-run this would not have been
    so lucky. ALREADY HAS A STATES BLOCK: now it is taken out first.
    """
    i = body.lower().find('states')
    if i < 0:
        return body
    j = body.find('{', i)
    if j < 0:
        return body
    depth = 0
    for k in range(j, len(body)):
        if body[k] == '{':
            depth += 1
        elif body[k] == '}':
            depth -= 1
            if depth == 0:
                return body[:i] + body[k + 1:]
    return body


def read(path):
    with io.open(path, encoding='utf-8', errors='replace', newline='') as fh:
        return fh.read()


def actor_body(text, name):
    """The text between an ACTOR's outermost braces, by counting them."""
    m = re.search(r'(?mi)^ACTOR\s+%s\b[^\n{]*\n?\s*\{' % re.escape(name), text)
    if not m:
        return None
    i = text.index('{', m.start())
    depth = 0
    for j in range(i, len(text)):
        if text[j] == '{':
            depth += 1
        elif text[j] == '}':
            depth -= 1
            if depth == 0:
                return text[i + 1:j]
    return None


def states_block(body):
    """The States { ... } block of an actor body, braces included in the count."""
    m = re.search(r'(?mi)^\s*States\s*\n?\s*\{', body)
    if not m:
        return None
    i = body.index('{', m.start())
    depth = 0
    for j in range(i, len(body)):
        if body[j] == '{':
            depth += 1
        elif body[j] == '}':
            depth -= 1
            if depth == 0:
                return body[i + 1:j]
    return None


def main():
    blob = ''
    for f in SRC:
        blob += read(os.path.join(ROOT, 'actors', 'weapons', f)) + '\n'

    dual_path = os.path.join(ROOT, 'DECORATE.aedual')
    dual = read(dual_path)
    eol = '\r\n' if '\r\n' in dual else '\n'

    done = 0
    for off, parent, oldmag, newmag in GUNS:
        body = actor_body(blob, parent)
        if body is None:
            print('!! parent not found: %s' % parent)
            continue
        st = states_block(body)
        if st is None:
            print('!! no States block in %s' % parent)
            continue

        # the substitution, and nothing else. Whole word, quoted or bare, any case.
        pat = re.compile(r'(?i)\b%s\b' % re.escape(oldmag))
        new_st, n = pat.subn(newmag, st)
        if n == 0:
            print('   %-24s no %s reference to swap' % (off, oldmag))

        # splice the states in before the off-hand actor's closing brace
        m = re.search(r'(?mi)^ACTOR\s+%s\b[^\n{]*\n?\s*\{' % re.escape(off), dual)
        if not m:
            print('!! off-hand actor not found: %s' % off)
            continue
        i = dual.index('{', m.start())
        depth = 0
        for j in range(i, len(dual)):
            if dual[j] == '{':
                depth += 1
            elif dual[j] == '}':
                depth -= 1
                if depth == 0:
                    break
        head = ('%s\t// GENERATED from %s: its whole state machine with %s -> %s (%d swapped).%s'
                '\t// Inheriting the parent\'s states instead would load the PARENT\'s magazine.%s'
                '\tStates%s\t{' % (eol, parent, oldmag, newmag, n, eol, eol, eol))
        dual = dual[:j] + head + new_st.rstrip() + eol + '\t}' + eol + dual[j:]
        print('   %-24s <- %-22s %3d x %s -> %s' % (off, parent, n, oldmag, newmag))
        done += 1

    io.open(dual_path, 'w', encoding='utf-8', newline='').write(dual)
    print('%d off-hand guns given their own states' % done)


if __name__ == '__main__':
    main()
